#!/bin/zsh
# Compiles the Icon Composer document (darwin/aether.icon) with actool and
# injects the resulting Assets.car into the built app bundle.
#
# macOS 26+ renders the Liquid Glass icon from Assets.car (matched via the
# CFBundleIconName=aether key in Info.plist). Older macOS versions ignore the
# asset catalog and fall back to CFBundleIconFile (iconfile.icns, generated by
# wails from build/appicon.png).
#
# Requires Xcode 26+ (actool). Run AFTER `wails build`:
#   wails build -platform darwin/arm64 && ./build/darwin/compile-icon.sh
#
# Usage: compile-icon.sh [path/to/App.app]   (default: build/bin/Aether.app)
set -euo pipefail

cd "$(dirname "$0")/../.."   # repo root

APP_BUNDLE="${1:-build/bin/Aether.app}"
ICON_NAME="aether"
ICON_FILE="build/darwin/${ICON_NAME}.icon"
RESOURCES_DIR="$APP_BUNDLE/Contents/Resources"

[[ -d "$ICON_FILE" ]] || { echo "error: $ICON_FILE not found" >&2; exit 1; }
[[ -d "$APP_BUNDLE" ]] || { echo "error: $APP_BUNDLE not found - run 'wails build' first" >&2; exit 1; }

PARTIAL_PLIST="$(mktemp -t actool-partial).plist"
trap 'rm -f "$PARTIAL_PLIST"' EXIT

# actool requires --output-partial-info-plist when --app-icon is given; the
# generated keys (CFBundleIconName=aether) are already in our Info.plist
# template, so the partial plist itself is discarded.
xcrun actool --compile "$RESOURCES_DIR" \
  --platform macosx \
  --minimum-deployment-target 26.0 \
  --app-icon "$ICON_NAME" \
  --output-partial-info-plist "$PARTIAL_PLIST" \
  --errors --warnings --notices --output-format human-readable-text \
  "$ICON_FILE"

# Adding Assets.car invalidates the bundle signature wails produced; re-sign ad hoc.
codesign --force --sign - "$APP_BUNDLE"

echo "OK: $ICON_FILE -> $RESOURCES_DIR/Assets.car"
